macro_rules! deps {
    () => {
        Value!();
        HexBytes!();
        DisplayValue!();
        ValueSet!();
        Field!();
        Event!();
        Subscriber!();
    };
}

macro_rules! Visit {
    () => {
        deps!();
        # [doc = " Visits typed values."] # [doc = ""] # [doc = " An instance of `Visit` (\"a visitor\") represents the logic necessary to"] # [doc = " record field values of various types. When an implementor of [`Value`] is"] # [doc = " [recorded], it calls the appropriate method on the provided visitor to"] # [doc = " indicate the type that value should be recorded as."] # [doc = ""] # [doc = " When a [`Subscriber`] implementation [records an `Event`] or a"] # [doc = " [set of `Value`s added to a `Span`], it can pass an `&mut Visit` to the"] # [doc = " `record` method on the provided [`ValueSet`] or [`Event`]. This visitor"] # [doc = " will then be used to record all the field-value pairs present on that"] # [doc = " `Event` or `ValueSet`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " A simple visitor that writes to a string might be implemented like so:"] # [doc = " ```"] # [doc = " # extern crate tracing_core as tracing;"] # [doc = " use std::fmt::{self, Write};"] # [doc = " use tracing::field::{Value, Visit, Field};"] # [doc = " pub struct StringVisitor<'a> {"] # [doc = "     string: &'a mut String,"] # [doc = " }"] # [doc = ""] # [doc = " impl<'a> Visit for StringVisitor<'a> {"] # [doc = "     fn record_debug(&mut self, field: &Field, value: &dyn fmt::Debug) {"] # [doc = "         write!(self.string, \"{} = {:?}; \", field.name(), value).unwrap();"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = " This visitor will format each recorded value using `fmt::Debug`, and"] # [doc = " append the field name and formatted value to the provided string,"] # [doc = " regardless of the type of the recorded value. When all the values have"] # [doc = " been recorded, the `StringVisitor` may be dropped, allowing the string"] # [doc = " to be printed or stored in some other data structure."] # [doc = ""] # [doc = " The `Visit` trait provides default implementations for `record_i64`,"] # [doc = " `record_u64`, `record_bool`, `record_str`, and `record_error`, which simply"] # [doc = " forward the recorded value to `record_debug`. Thus, `record_debug` is the"] # [doc = " only method which a `Visit` implementation *must* implement. However,"] # [doc = " visitors may override the default implementations of these functions in"] # [doc = " order to implement type-specific behavior."] # [doc = ""] # [doc = " Additionally, when a visitor receives a value of a type it does not care"] # [doc = " about, it is free to ignore those values completely. For example, a"] # [doc = " visitor which only records numeric data might look like this:"] # [doc = ""] # [doc = " ```"] # [doc = " # extern crate tracing_core as tracing;"] # [doc = " # use std::fmt::{self, Write};"] # [doc = " # use tracing::field::{Value, Visit, Field};"] # [doc = " pub struct SumVisitor {"] # [doc = "     sum: i64,"] # [doc = " }"] # [doc = ""] # [doc = " impl Visit for SumVisitor {"] # [doc = "     fn record_i64(&mut self, _field: &Field, value: i64) {"] # [doc = "        self.sum += value;"] # [doc = "     }"] # [doc = ""] # [doc = "     fn record_u64(&mut self, _field: &Field, value: u64) {"] # [doc = "         self.sum += value as i64;"] # [doc = "     }"] # [doc = ""] # [doc = "     fn record_debug(&mut self, _field: &Field, _value: &fmt::Debug) {"] # [doc = "         // Do nothing"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This visitor (which is probably not particularly useful) keeps a running"] # [doc = " sum of all the numeric values it records, and ignores all other values. A"] # [doc = " more practical example of recording typed values is presented in"] # [doc = " `examples/counters.rs`, which demonstrates a very simple metrics system"] # [doc = " implemented using `tracing`."] # [doc = ""] # [doc = " <div class=\"example-wrap\" style=\"display:inline-block\">"] # [doc = " <pre class=\"ignore\" style=\"white-space:normal;font:inherit;\">"] # [doc = " <strong>Note</strong>: The <code>record_error</code> trait method is only"] # [doc = " available when the Rust standard library is present, as it requires the"] # [doc = " <code>std::error::Error</code> trait."] # [doc = " </pre></div>"] # [doc = ""] # [doc = " [recorded]: Value::record"] # [doc = " [`Subscriber`]: super::subscriber::Subscriber"] # [doc = " [records an `Event`]: super::subscriber::Subscriber::event"] # [doc = " [set of `Value`s added to a `Span`]: super::subscriber::Subscriber::record"] # [doc = " [`Event`]: super::event::Event"] pub trait Visit { # [doc = " Visits an arbitrary type implementing the [`valuable`] crate's `Valuable` trait."] # [doc = ""] # [doc = " [`valuable`]: https://docs.rs/valuable"] # [cfg (all (tracing_unstable , feature = "valuable"))] # [cfg_attr (docsrs , doc (cfg (all (tracing_unstable , feature = "valuable"))))] fn record_value (& mut self , field : & Field , value : valuable :: Value < '_ >) { self . record_debug (field , & value) } # [doc = " Visit a double-precision floating point value."] fn record_f64 (& mut self , field : & Field , value : f64) { self . record_debug (field , & value) } # [doc = " Visit a signed 64-bit integer value."] fn record_i64 (& mut self , field : & Field , value : i64) { self . record_debug (field , & value) } # [doc = " Visit an unsigned 64-bit integer value."] fn record_u64 (& mut self , field : & Field , value : u64) { self . record_debug (field , & value) } # [doc = " Visit a signed 128-bit integer value."] fn record_i128 (& mut self , field : & Field , value : i128) { self . record_debug (field , & value) } # [doc = " Visit an unsigned 128-bit integer value."] fn record_u128 (& mut self , field : & Field , value : u128) { self . record_debug (field , & value) } # [doc = " Visit a boolean value."] fn record_bool (& mut self , field : & Field , value : bool) { self . record_debug (field , & value) } # [doc = " Visit a string value."] fn record_str (& mut self , field : & Field , value : & str) { self . record_debug (field , & value) } # [doc = " Visit a byte slice."] fn record_bytes (& mut self , field : & Field , value : & [u8]) { self . record_debug (field , & HexBytes (value)) } # [doc = " Records a type implementing `Error`."] # [doc = ""] # [doc = " <div class=\"example-wrap\" style=\"display:inline-block\">"] # [doc = " <pre class=\"ignore\" style=\"white-space:normal;font:inherit;\">"] # [doc = " <strong>Note</strong>: This is only enabled when the Rust standard library is"] # [doc = " present."] # [doc = " </pre>"] # [doc = " </div>"] # [cfg (feature = "std")] # [cfg_attr (docsrs , doc (cfg (feature = "std")))] fn record_error (& mut self , field : & Field , value : & (dyn std :: error :: Error + 'static)) { self . record_debug (field , & DisplayValue (value)) } # [doc = " Visit a value implementing `fmt::Debug`."] fn record_debug (& mut self , field : & Field , value : & dyn fmt :: Debug) ; }
    };
}

Visit!()